def transform(grid):
    """Reflect lone motifs into their adjacent empty tile in the same band."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    hr = [r for r in range(h) if g[r][0] != 0 and all(v == g[r][0] for v in g[r])]
    vc = [c for c in range(w) if g[0][c] != 0 and all(g[r][c] == g[0][c] for r in range(h))]
    rb, cb = [-1] + hr + [h], [-1] + vc + [w]
    for ri in range(len(rb)-1):
        r0, r1 = rb[ri]+1, rb[ri+1]
        if r0 >= r1: continue
        for ci in range(len(cb)-1):
            c0, c1 = cb[ci]+1, cb[ci+1]
            if c0 >= c1: continue
            if not any(g[r][c] for r in range(r0,r1) for c in range(c0,c1)): continue
            # Only copy when the tile's designated adjacent partner is blank;
            # default pair is to the right, matching observed demonstrations.
            candidates = []
            if ci+1 < len(cb)-1:
                candidates.append((ci+1, c1+1, cb[ci+2]))
            if ci > 0:
                candidates.append((ci-1, cb[ci-1]+1, cb[ci]))
            for partner, p0, p1 in candidates:
                if not any(g[r][c] for r in range(r0,r1) for c in range(p0,p1)):
                    # Prefer the right tile; use the left only when no right tile exists.
                    for r in range(r0,r1):
                        for c in range(c0,c1):
                            v=g[r][c]
                            if v:
                                local=c-c0
                                g[r][p0+(c1-c0-1-local)] = v
                    break
    return g
